"""Path resolution for the MetaDNS ICML 2026 reproduction notebooks.

The notebooks use their original ``HOME_DIR / "slurm_files/<run>/..."`` path
code. This module provides a drop-in ``HOME_DIR`` whose ``/`` operator remaps
those legacy paths onto the flattened Zenodo layout::

    data/<system>/<category>/<run>/{samples.pkl, weights_final.pth, config.json}
    data/<system>/baselines/<name>/...        MCMC / SW / Wang-Landau
    data/<system>/wt_metad/<name>/...          WT-MetaD baselines
    data/<system>/metadns_ckpts/<name>/...     convergence checkpoint sequences

DATA_ROOT defaults to the repository ``checkpoints/`` directory, where the
Zenodo ``data_{ising,potts,cuau}.tar.gz`` archives are meant to be extracted
(see the README). It must contain ``ising/``, ``potts/`` and/or ``cuau/``
trees. Override with the ``METADNS_DATA_ROOT`` environment variable.

Notebook usage (already injected): ``from paths import HOME_DIR, DATA_ROOT, glob``
"""
import os
import glob as _glob
from pathlib import Path

DATA_ROOT = Path(os.environ.get(
    "METADNS_DATA_ROOT",
    Path(__file__).resolve().parent.parent / "checkpoints",
))

